from pathlib import Path

root = Path(__file__).resolve().parents[1]
p = root / 'lib/settings_pages.dart'
text = p.read_text(encoding='utf-8')

def r(old, new):
    global text
    n = text.count(old)
    if n == 0:
        print('WARN settings_pages:', repr(old[:100]))
    else:
        print('settings_pages:', n, 'x', repr(old[:60]))
        text = text.replace(old, new)

